// Bit-exact parity test for the full-sequence GDN PREFILL (S > 1) path.
// Compares C++ gdn_prefill against vectors generated by the REAL
// Qwen4ExpGatedDeltaNet.__call__ (tools/gen_prefill_vectors.py), viewing float
// results as raw uint32 bits — byte-for-byte, not by tolerance.
//
// Usage: test_prefill <vectordir>
#include "../src/prefill.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

#include <dirent.h>
#include <sys/stat.h>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) return false;
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static void dump_first_diff(const char* label, const mx::array& a,
                            const mx::array& b) {
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i) {
    if (pa[i] != pb[i]) {
      std::fprintf(stderr, "  %s first diff at %zu: got 0x%08x expected 0x%08x\n",
                   label, i, pa[i], pb[i]);
      return;
    }
  }
}

static bool is_dir(const std::string& path) {
  struct stat st;
  return stat(path.c_str(), &st) == 0 && S_ISDIR(st.st_mode);
}

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <vectordir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  auto load = [&](const std::string& p) { return mx::load(p); };

  // Shared weights (saved once at the top level by the generator).
  mx::array w_qkv = load(dir + "/w_qkv.npy"), w_z = load(dir + "/w_z.npy");
  mx::array w_b = load(dir + "/w_b.npy"), w_a = load(dir + "/w_a.npy");
  mx::array conv_w = load(dir + "/conv_w.npy"), A_log = load(dir + "/A_log.npy");
  mx::array dt_bias = load(dir + "/dt_bias.npy"), norm_w = load(dir + "/norm_w.npy");
  mx::array w_out = load(dir + "/w_out.npy");
  GDNWeights weights(w_qkv, w_z, w_b, w_a, conv_w, A_log, dt_bias,
                     norm_w, w_out);

  // Derive geometry from the saved weight shapes (tracks the generator).
  const int H = w_qkv.shape(1);
  const int conv_dim = w_qkv.shape(0);
  const int value_dim = w_z.shape(0);
  const int key_dim = (conv_dim - value_dim) / 2;
  const int Hv = A_log.shape(0);
  const int Dv = norm_w.shape(0);

  // Enumerate case subdirectories (s2, s5, s16, s5_masked, ...).
  std::vector<std::string> cases;
  DIR* d = opendir(dir.c_str());
  if (d == nullptr) {
    std::fprintf(stderr, "cannot open vectordir %s\n", dir.c_str());
    return 2;
  }
  struct dirent* ent;
  while ((ent = readdir(d)) != nullptr) {
    std::string name = ent->d_name;
    if (name == "." || name == "..") continue;
    if (is_dir(dir + "/" + name) && name != "__pycache__") cases.push_back(name);
  }
  closedir(d);

  bool all_ok = true;
  int passed = 0;
  for (const std::string& c : cases) {
    const std::string p = dir + "/" + c;
    mx::array x = load(p + "/x.npy");
    const int S = x.shape(1);
    const int Dk_case = load(p + "/i_rec_state.npy").shape(3);
    const int Hk = key_dim / Dk_case;
    const int K = load(p + "/i_conv_state.npy").shape(1) + 1;

    GDNConfig cfg{H, key_dim, value_dim, Hk, Hv, Dk_case, Dv, K,
                  1e-6f, GDNActivation::Sigmoid};

    // Initial cache saved by the generator BEFORE the model call (the layer
    // reassigns cache[0]/cache[1], so expected_* hold the advanced cache).
    mx::array i_conv = load(p + "/i_conv_state.npy");
    mx::array i_rec = load(p + "/i_rec_state.npy");
    GDNCacheState cache(i_conv, i_rec);

    mx::array mask = load(p + "/mask.npy");
    const mx::array* mask_ptr = mask.size() > 0 ? &mask : nullptr;

    GDNLayerOutput got = gdn_prefill(x, weights, cache, cfg, mask_ptr);
    mx::eval(got.output, got.conv_state, got.recurrent_state);

    mx::array exp_out = load(p + "/expected_output.npy");
    mx::array exp_conv = load(p + "/expected_conv_state.npy");
    mx::array exp_rec = load(p + "/expected_rec_state.npy");

    bool ok = true;
    if (!bit_equal(got.output, exp_out)) {
      std::fprintf(stderr, "FAIL [%s S=%d]: layer output differs\n", c.c_str(), S);
      dump_first_diff("output", got.output, exp_out);
      ok = false;
    }
    if (!bit_equal(got.conv_state, exp_conv)) {
      std::fprintf(stderr, "FAIL [%s S=%d]: new conv_state differs\n", c.c_str(), S);
      dump_first_diff("conv_state", got.conv_state, exp_conv);
      ok = false;
    }
    if (!bit_equal(got.recurrent_state, exp_rec)) {
      std::fprintf(stderr, "FAIL [%s S=%d]: new recurrent_state differs\n", c.c_str(), S);
      dump_first_diff("rec_state", got.recurrent_state, exp_rec);
      ok = false;
    }
    if (ok) {
      std::printf("  case %s (S=%d, mask=%s): OK (bit-exact)\n", c.c_str(), S,
                  mask_ptr ? "yes" : "no");
      ++passed;
    } else {
      all_ok = false;
    }
  }

  if (!all_ok || passed == 0) return 1;
  std::printf("test_prefill OK (%d cases, bit-exact)\n", passed);
  return 0;
}
